<section class="dash-card" id="proposals"><div class="card-title"><h2>پیشنهادهای دریافتی</h2><span><?=count($proposals)?> پیشنهاد</span></div><?php foreach($proposals as $proposal):?><article class="proposal-card"><div class="proposal-row"><strong><?=e($proposal['freelancer_name']?:'فریلنسر')?> · <?=e($proposal['title'])?></strong><span><?=e($proposal['bid_amount'])?> دلار · <?=e($proposal['status'])?></span></div><p><?=e($proposal['cover_letter'])?></p><?php if($proposal['status']==='pending'):?><div class="proposal-actions"><form class="inline-form" method="post" action="<?=url('/dashboard/employer/proposals/status')?>"><?=csrf_field()?><input type="hidden" name="proposal_id" value="<?=e($proposal['id'])?>"><input type="hidden" name="status" value="accepted"><button class="button button-small" type="submit">پذیرش و ایجاد قرارداد</button></form><form class="inline-form" method="post" action="<?=url('/dashboard/employer/proposals/status')?>"><?=csrf_field()?><input type="hidden" name="proposal_id" value="<?=e($proposal['id'])?>"><input type="hidden" name="status" value="rejected"><button class="button button-small secondary" type="submit">رد پیشنهاد</button></form></div><?php endif;?><form class="proposal-reply" method="post" action="<?=url('/dashboard/employer/proposals/reply')?>"><?=csrf_field()?><input type="hidden" name="proposal_id" value="<?=e($proposal['id'])?>"><input name="body" placeholder="پاسخ برای فریلنسر..."><button class="button button-small" type="submit">ارسال پاسخ</button></form></article><?php endforeach;?><?php if(!$proposals):?><p class="muted">هنوز پیشنهادی دریافت نکرده‌اید.</p><?php endif;?></section>